package com.huawei.aisfsdkv2.component.androidfunc.accessibility.model;

/**
 * 系统按键类型
 */
public enum SystemKey {
    /** 主页键 */
    HOME,

    /** 返回键 */
    BACK,

    /** 最近任务键 */
    RECENTS,

    /** 确认/回车键 */
    ENTER,

    /** 电源键（需特殊权限，可能不可用） */
    POWER
}
